package run.ikaros.music;
import java.time.Instant; import java.util.UUID; import org.springframework.core.io.buffer.DataBufferUtils; import org.springframework.stereotype.Service; import org.springframework.transaction.reactive.TransactionalOperator; import run.ikaros.common.NotFoundException; import run.ikaros.storage.api.AttachmentContentService; import run.ikaros.storage.api.StorageService; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@Service public class PersistentMusicMetadataRecognitionService implements MusicMetadataRecognitionService {
    private static final int MAX_METADATA_BYTES=1024*1024; private final MusicTrackRepository tracks; private final MusicAudioSourceService sources; private final StorageService storage; private final AttachmentContentService content; private final MusicMetadataCandidateRepository candidates; private final TransactionalOperator transaction;
    public PersistentMusicMetadataRecognitionService(MusicTrackRepository tracks,MusicAudioSourceService sources,StorageService storage,AttachmentContentService content,MusicMetadataCandidateRepository candidates,TransactionalOperator transaction){this.tracks=tracks;this.sources=sources;this.storage=storage;this.content=content;this.candidates=candidates;this.transaction=transaction;}
    @Override public Mono<MusicMetadataCandidateView> recognize(UUID ownerId,UUID trackId){return tracks.findById(trackId).filter(t->t.ownerId().equals(ownerId)).switchIfEmpty(Mono.error(new NotFoundException("Track 不存在或无权访问"))).flatMap(t->sources.list(ownerId,t.id()).next().switchIfEmpty(Mono.error(new NotFoundException("Track 没有可识别的 Audio Source")))).flatMap(source->storage.get(ownerId,source.attachmentId()).flatMap(attachment->read(ownerId,source.attachmentId()).map(bytes->MusicTagParser.parse(attachment.fileName(),bytes)).flatMap(parsed->save(ownerId,trackId,source.attachmentId(),parsed)))).as(transaction::transactional);}
    @Override public Flux<MusicMetadataCandidateView> list(UUID ownerId,UUID trackId){return tracks.findById(trackId).filter(t->t.ownerId().equals(ownerId)).switchIfEmpty(Mono.error(new NotFoundException("Track 不存在或无权访问"))).thenMany(candidates.findAllByOwnerIdAndTrackIdOrderByCreatedAtDesc(ownerId,trackId).map(this::view));}
    private Mono<byte[]> read(UUID ownerId,UUID attachmentId){return DataBufferUtils.join(content.read(ownerId,attachmentId),MAX_METADATA_BYTES).map(buffer->{try{byte[] bytes=new byte[buffer.readableByteCount()];buffer.read(bytes);return bytes;}finally{DataBufferUtils.release(buffer);}});}
    private Mono<MusicMetadataCandidateView> save(UUID ownerId,UUID trackId,UUID attachmentId,MusicTagParser.Parsed p){return candidates.findByOwnerIdAndTrackIdAndAttachmentId(ownerId,trackId,attachmentId).defaultIfEmpty(new MusicMetadataCandidateEntity(null,ownerId,trackId,attachmentId,null,null,null,null,null,null,null,null,null,p.source(),null,null,null)).flatMap(old->{Instant now=Instant.now();return candidates.save(new MusicMetadataCandidateEntity(old.id(),ownerId,trackId,attachmentId,p.title(),p.artist(),p.album(),p.albumArtist(),p.isrc(),p.genre(),p.trackNumber(),p.discNumber(),p.releaseYear(),p.source(),old.createdAt()==null?now:old.createdAt(),now,old.version())).map(this::view);});}
    private MusicMetadataCandidateView view(MusicMetadataCandidateEntity e){return new MusicMetadataCandidateView(e.id(),e.trackId(),e.attachmentId(),e.title(),e.artist(),e.album(),e.albumArtist(),e.isrc(),e.genre(),e.trackNumber(),e.discNumber(),e.releaseYear(),e.source(),e.createdAt(),e.updatedAt());}
}
